		__( "This screen lists your store data. Use the status tabs and filters above the list to narrow it down, click a column header to sort, and use the Screen Options tab to choose which columns appear and how many items load per page. Your preferences are saved to your account.", "storeengine" );
		__( "Screen Content", "storeengine" );
		__( "You can customise what this screen shows:", "storeengine" );
		__( "Open Screen Options (top-right) to show or hide columns.", "storeengine" );
		__( "Reorder columns by dragging them in the table’s column manager.", "storeengine" );
		__( "Set how many items load per page from Screen Options.", "storeengine" );
		__( "Available Actions", "storeengine" );
		__( "Hover over a row to reveal its actions:", "storeengine" );
		__( "Edit — open the item’s editing screen (or click its title).", "storeengine" );
