		__( "Delete / Trash — remove the item.", "storeengine" );
		__( "Bulk Actions", "storeengine" );
		__( "Select one or more rows using the checkboxes, choose an action from the Bulk actions menu, and apply it to all selected items at once.", "storeengine" );
		__( "The Orders screen lists every order placed in your store. Filter by status, search by customer or order number, and open an order to view its items, payments, and fulfilment.", "storeengine" );
		__( "The Products screen is your catalog. Create and edit products, manage pricing and variations, and control what appears in your store.", "storeengine" );
		__( "The Customers screen lists everyone who has an account or has purchased from you. Open a customer to see their orders, subscriptions, and purchased items.", "storeengine" );
		__( "The Subscriptions screen tracks recurring plans. Filter by status to find active, on-hold, or cancelled subscriptions and open one to manage its billing.", "storeengine" );
		__( "The Payments screen is a record of every transaction processed through your store, including the gateway used and each payment’s status.", "storeengine" );
		__( "The Access Groups screen manages membership rules that grant customers access to protected content based on the products they own.", "storeengine" );
		__( "The Coupons screen lists your discount codes. Create fixed or percentage discounts, set usage limits and expiry, and track how each coupon is performing.", "storeengine" );
		__( "The Logs screen records system events and errors. Filter by module or status to diagnose issues; open an entry for its full detail.", "storeengine" );
		__( "The Affiliates screen lists partners promoting your store. Approve applications, set commission rates, and review each affiliate’s performance.", "storeengine" );
		__( "The Commissions screen records the earnings owed to affiliates for referred sales, along with each commission’s current status.", "storeengine" );
		__( "The Payouts screen tracks money paid out to affiliates. Review pending balances and mark payouts as completed.", "storeengine" );
		__( "The Clicks screen logs referral link visits so you can see the traffic each affiliate is sending to your store.", "storeengine" );
		__( "The Email Logs screen records the emails your store has sent. Filter by type or status and open an entry to inspect the message.", "storeengine" );
		__( "The Funnels screen lists your sales funnels — the checkout and one-click upsell flows that guide customers through a purchase.", "storeengine" );
		__( "The Tags screen manages product tags, a flexible way to label and group products for filtering and merchandising.", "storeengine" );
		__( "This screen manages your product taxonomies — categories, tags, and brands — used to organise your catalog.", "storeengine" );
		__( "The Attributes screen defines reusable product attributes (such as size or colour) and their terms, which power product variations and filtering.", "storeengine" );
		__( "The Inventory screen shows stock levels across your catalog. Spot low-stock items and adjust quantities in place.", "storeengine" );
		__( "The Incoming Webhooks screen manages endpoints that let external services send data into your store.", "storeengine" );
		__( "The Webhooks screen manages outgoing notifications your store sends to external URLs when events occur.", "storeengine" );
		__( "The Order Bumps screen manages the optional add-on offers shown to customers at checkout to increase order value.", "storeengine" );
		__( "The Installment Plans screen manages pay-over-time plans that split a purchase into scheduled payments.", "storeengine" );
		__( "The Licenses screen lists software licenses issued for your products, including their activation status and linked sites.", "storeengine" );
		__( "The Abandoned Carts screen surfaces checkouts customers started but didn’t complete, so you can recover potentially lost sales.", "storeengine" );
