		__( "Applied when creating a new product. Digital products skip the inventory section; physical products show it by default.", "storeengine" );
		__( "Adds a Buy Now button alongside Add to Cart. When the Instant Checkout addon is active, Buy Now opens the Quick Checkout modal instead of redirecting to the checkout page.", "storeengine" );
		__( "Forces quantity to 1. Ideal for digital products that are bought one at a time.", "storeengine" );
		__( "Hides the Add to Cart button and shows only the Buy Now button for instant checkout.", "storeengine" );
		__( "Sticky Add to Cart", "storeengine" );
		__( "Shows a fixed bottom bar on single product pages with the thumbnail, name, live price and an Add to Cart button, once the main button scrolls out of view. Applies on all screen sizes.", "storeengine" );
		__( "Recently viewed products", "storeengine" );
		__( "Shows a \"Recently viewed\" row on single product pages, built from the shopper’s own browsing (stored in their browser).", "storeengine" );
		__( "Shows a \"Size guide\" link on product pages and in Quick View. Build measurement tables under Products → Size Charts and assign each one to categories, brands or specific products — a product shows the most specific match, and no link at all when nothing matches.", "storeengine" );
		__( "Product compare", "storeengine" );
		__( "Adds a \"Compare\" toggle over the product image on shop cards, plus one on product pages and in Quick View. Picks collect in a docked tray, and the side-by-side table opens in a modal — no page to set up. Use [storeengine_compare_count] for a badge, or [storeengine_compare] to embed the table in a page.", "storeengine" );
		__( "Wishlist", "storeengine" );
		__( "Adds a wishlist (heart) button on shop cards, product pages and Quick View. Saved to the account for logged-in shoppers, and to the browser for guests. Use the [storeengine_wishlist] shortcode for the wishlist page.", "storeengine" );
		__( "Let shoppers browse a product gallery images on the shop card (arrows, dots and swipe).", "storeengine" );
		__( "Show color/image swatches on shop cards; picking one swaps the card image.", "storeengine" );
